/**
 * Wraps an async iterable so that the provided span is ended once iteration
 * completes, is aborted, or throws. Any error encountered during iteration is
 * recorded on the span and then re-thrown.
 */
async function* wrapIterableWithSpanEnd<T>(
  iterable: AsyncIterable<T>,
  meta: SpanMetadata,
  endSpan: () => void,
): AsyncGenerator<T> {
  try {
    for await (const item of iterable) {
      yield item;
    }
  } catch (e) {
    meta.error = e;
    // Re-throw after the span has been ended (see the finally block below).
    throw e;
  } finally {
    endSpan();
  }
